import symbolMap from './symbols.json';

/**
 * Which picture goes with which word.
 *
 * The mapping is generated by scripts/build-symbols.mjs. Words that are missing
 * from it are shown as text-only tiles: mostly small grammar words ("of",
 * "if", "the") for which a picture would only be decoration.
 */
const SYMBOLS: Record<string, string> = symbolMap;

/** Address of the bundled picture for a word, or null when it has none. */
export function symbolUrl(wordId: string): string | null {
  const key = SYMBOLS[wordId];
  return key ? `${import.meta.env.BASE_URL}symbols/${key}.svg` : null;
}

export function hasSymbol(wordId: string): boolean {
  return wordId in SYMBOLS;
}

/** Every bundled picture path (without extension), for tests. */
export function allSymbolKeys(): string[] {
  return Array.from(new Set(Object.values(SYMBOLS)));
}
